const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const toshkaLakes = ee.Geometry.Polygon([[
        [30.2, 23.3],
        [31.8, 23.3],
        [31.8, 22.2],
        [30.2, 22.2],
        [30.2, 23.3]
    ]]);
    const date_2002 = ee.DateRange('2002-09-01', '2002-09-30');
    const date_2012 = ee.DateRange('2012-06-01', '2012-06-30');

    // Function to mask clouds in Landsat 7 C2 L2 data
    const maskL7clouds = (image) => {
        const qa = image.select('QA_PIXEL');
        // Bit 5 is cloud, bit 7 is cloud shadow
        const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 7));
        return image.updateMask(cloud.not());
    };

    // Function to calculate NDWI for Landsat 7
    const addNDWI_L7 = (image) => {
        // Green: B2, NIR: B4 for Landsat 7
        const ndwi = image.normalizedDifference(['SR_B2', 'SR_B4']).rename('ndwi');
        return image.addBands(ndwi);
    };

    // Function to calculate water area for a given image
    const calculateWaterArea = (image) => {
        const waterMask = image.select('ndwi').gt(0);
        const waterArea = waterMask.multiply(ee.Image.pixelArea()).reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: toshkaLakes,
            scale: 1000,
            maxPixels: 1e9
        });
        return ee.Number(waterArea.get('ndwi')).divide(1e6); // Convert to sq km
    };

    // 2. Data Acquisition & Processing
    // Period 1: September 2002 (Landsat 7)
    const collection2002 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterBounds(toshkaLakes)
        .filterDate(date_2002);

    // Period 2: June 2012 (Landsat 7)
    const collection2012 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterBounds(toshkaLakes)
        .filterDate(date_2012);

    const count2002 = collection2002.size().getInfo();
    const count2012 = collection2012.size().getInfo();

    if (count2002 === 0 || count2012 === 0) {
        console.log(`Image count 2002: ${count2002}`);
        console.log(`Image count 2012: ${count2012}`);
        console.log("Empty image collection for one or both periods.");
        console.log("C1");
        return;
    }

    const image2002 = collection2002.map(maskL7clouds).map(addNDWI_L7).median();
    const image2012 = collection2012.map(maskL7clouds).map(addNDWI_L7).median();

    // 3. Pixel Count Validation
    const validPixels2002 = image2002.select('ndwi').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: toshkaLakes,
        scale: 3000,
        maxPixels: 1e9
    }).get('ndwi').getInfo();

    const validPixels2012 = image2012.select('ndwi').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: toshkaLakes,
        scale: 3000,
        maxPixels: 1e9
    }).get('ndwi').getInfo();

    if (validPixels2002 === 0 || validPixels2012 === 0) {
        console.log(`Valid pixels 2002: ${validPixels2002}`);
        console.log(`Valid pixels 2012: ${validPixels2012}`);
        console.log("No valid pixels after cloud masking.");
        console.log("C2");
        return;
    }

    // 4. Calculation
    const area2002 = calculateWaterArea(image2002).getInfo();
    const area2012 = calculateWaterArea(image2012).getInfo();

    if (area2002 === null || area2012 === null) {
        console.log("Calculation failed, result is null.");
        console.log("C3");
        return;
    }

    // 5. Validation & Final Answer
    console.log(`Image Count (2002): ${count2002}`);
    console.log(`Valid Pixels (2002): ${validPixels2002}`);
    console.log(`Surface Water Area Sep 2002 (sq km): ${area2002.toFixed(2)}`);
    console.log(`Image Count (2012): ${count2012}`);
    console.log(`Valid Pixels (2012): ${validPixels2012}`);
    console.log(`Surface Water Area Jun 2012 (sq km): ${area2012.toFixed(2)}`);

    if (area2012 < area2002) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during initialization or analysis:', e);
        console.log("D");
    }
}

initEE();
